:root{
  --ivory:#fdf8f4;
  --warm:#f9f1e8;
  --rose:#c4788a;
  --blush:#e8aab7;
  --dark:#2c1a20;
  --muted:#8a7070;
  --gold:#b89060;
}
*{margin:0;padding:0;box-sizing:border-box}
html{scroll-behavior:smooth}
body{background:var(--ivory);color:var(--dark);font-family:'Jost',sans-serif;overflow-x:hidden}
img{max-width:100%;display:block}
a{text-decoration:none;color:inherit}

/* TEXTURE */
body::before{
  content:'';position:fixed;inset:0;pointer-events:none;z-index:0;
  background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.75' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.03'/%3E%3C/svg%3E");
  opacity:.6;
}

/* NAV */
nav{
  position:fixed;top:0;left:0;right:0;z-index:100;
  background:rgba(253,248,244,.96);backdrop-filter:blur(16px);
  border-bottom:1px solid rgba(196,120,138,.12);
  padding:0 48px;height:72px;
  display:flex;align-items:center;justify-content:space-between;
}
.logo{
  font-family:'Cormorant Garamond',serif;font-size:22px;font-weight:600;
  letter-spacing:1px;color:var(--dark);
}
.logo em{color:var(--rose);font-style:italic}
.logo span{display:block;font-size:10px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);font-family:'Jost',sans-serif;font-weight:300;margin-top:1px}
.nav-links{display:flex;gap:36px;align-items:center}
.nav-links a{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);transition:.3s;font-weight:400}
.nav-links a:hover{color:var(--rose)}
.nav-cta{
  background:var(--rose);color:#fff;padding:10px 28px;
  font-size:11px;letter-spacing:2px;text-transform:uppercase;
  font-weight:500;transition:.3s;
}
.nav-cta:hover{background:var(--dark)}

/* HERO */
.hero{
  min-height:100vh;padding-top:72px;
  display:grid;grid-template-columns:45% 55%;
  position:relative;
}
.hero-left{
  display:flex;flex-direction:column;justify-content:center;
  padding:80px 48px;background:var(--warm);
  position:relative;z-index:1;
}
.hero-tag{
  display:flex;align-items:center;gap:12px;margin-bottom:32px;
}
.hero-tag span{
  font-size:10px;letter-spacing:4px;text-transform:uppercase;color:var(--rose);font-weight:500;
}
.hero-tag::before,.hero-tag::after{content:'';flex:1;height:1px;background:rgba(196,120,138,.25)}
.hero h1{
  font-family:'Cormorant Garamond',serif;
  font-size:clamp(52px,5vw,90px);
  font-weight:300;line-height:.95;
  color:var(--dark);margin-bottom:24px;
}
.hero h1 em{
  font-style:italic;color:var(--rose);display:block;font-size:clamp(60px,6vw,105px);
}
.hero-desc{
  font-size:15px;line-height:1.8;color:var(--muted);
  max-width:380px;margin-bottom:40px;
}
.hero-ctas{display:flex;gap:16px;flex-wrap:wrap;margin-bottom:48px}
.btn-rose{
  background:var(--rose);color:#fff;padding:14px 36px;
  font-size:11px;letter-spacing:3px;text-transform:uppercase;
  font-weight:500;transition:.3s;display:inline-flex;align-items:center;gap:10px;
}
.btn-rose:hover{background:var(--dark)}
.btn-border{
  border:1.5px solid var(--dark);color:var(--dark);padding:14px 36px;
  font-size:11px;letter-spacing:3px;text-transform:uppercase;
  font-weight:500;transition:.3s;
}
.btn-border:hover{background:var(--dark);color:var(--ivory)}
.hero-badges{display:flex;gap:20px}
.badge{
  text-align:center;padding:16px 20px;
  border:1px solid rgba(196,120,138,.15);
  background:rgba(232,170,183,.08);
}
.badge-num{
  font-family:'Cormorant Garamond',serif;font-size:36px;
  color:var(--rose);line-height:1;font-weight:600;
}
.badge-lbl{font-size:10px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-top:4px}

.hero-right{
  position:relative;overflow:hidden;
}
.hero-right img{
  width:100%;height:100%;object-fit:cover;object-position:center top;
}
.hero-right::before{
  content:'';position:absolute;left:0;top:0;bottom:0;width:80px;z-index:1;
  background:linear-gradient(90deg,var(--warm),transparent);
}
.hero-price-tag{
  position:absolute;bottom:40px;left:40px;z-index:2;
  background:var(--ivory);padding:20px 28px;
  border-left:3px solid var(--rose);
}
.price-label{font-size:10px;letter-spacing:3px;text-transform:uppercase;color:var(--muted)}
.price-val{font-family:'Cormorant Garamond',serif;font-size:32px;color:var(--rose);font-weight:600}

/* MARQUEE */
.marquee-bar{
  background:var(--rose);overflow:hidden;padding:12px 0;
}
.marquee-track{
  display:flex;gap:48px;animation:marquee 20s linear infinite;white-space:nowrap;
}
.marquee-track span{
  font-size:11px;letter-spacing:4px;text-transform:uppercase;color:rgba(255,255,255,.85);
  display:flex;align-items:center;gap:16px;
}
.marquee-track span::after{content:'✦';opacity:.6}
@keyframes marquee{from{transform:translateX(0)}to{transform:translateX(-50%)}}

/* SECTIONS */
.container{max-width:1200px;margin:0 auto;padding:0 48px}
section{padding:100px 0;position:relative;z-index:1}

.section-label{
  font-size:10px;letter-spacing:5px;text-transform:uppercase;color:var(--rose);
  margin-bottom:12px;display:flex;align-items:center;gap:12px;
}
.section-label::before{content:'';width:24px;height:1px;background:var(--rose)}
.section-title{
  font-family:'Cormorant Garamond',serif;
  font-size:clamp(36px,4vw,60px);font-weight:300;
  color:var(--dark);line-height:1.1;margin-bottom:16px;
}
.section-title em{color:var(--rose);font-style:italic}

/* SERVICES */
.services-section{background:var(--warm)}
.services-intro{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:end;margin-bottom:64px}
.services-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(196,120,138,.12)}
.srv{
  background:var(--warm);padding:40px 32px;transition:.4s;
  position:relative;overflow:hidden;
}
.srv::after{
  content:'';position:absolute;bottom:0;left:0;right:0;height:2px;
  background:var(--rose);transform:scaleX(0);transition:.4s;transform-origin:left;
}
.srv:hover{background:var(--ivory)}
.srv:hover::after{transform:scaleX(1)}
.srv-num{
  font-family:'Cormorant Garamond',serif;font-size:56px;font-weight:300;
  color:rgba(196,120,138,.15);line-height:1;margin-bottom:8px;
  position:absolute;top:24px;right:24px;
}
.srv-icon{font-size:28px;margin-bottom:16px;display:block}
.srv-name{
  font-family:'Cormorant Garamond',serif;font-size:24px;font-weight:600;
  color:var(--dark);margin-bottom:8px;
}
.srv-desc{font-size:13px;line-height:1.7;color:var(--muted);margin-bottom:20px}
.srv-price{
  font-family:'Cormorant Garamond',serif;font-size:28px;color:var(--rose);font-weight:600;
}
.srv-price span{font-size:12px;font-family:'Jost',sans-serif;color:var(--muted);letter-spacing:1px}

/* FEATURED / ABOUT */
.about-section{background:var(--ivory)}
.about-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.about-photos{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.about-photos img{width:100%;aspect-ratio:3/4;object-fit:cover}
.about-photos img:nth-child(2){margin-top:40px}
.about-quote{
  font-family:'Cormorant Garamond',serif;font-size:22px;font-style:italic;
  color:var(--rose);line-height:1.6;margin:24px 0;
  padding-left:24px;border-left:2px solid var(--blush);
}
.about-p{font-size:15px;line-height:1.8;color:var(--muted);margin-bottom:16px}

/* GALLERY */
.gallery-section{background:var(--dark);padding:100px 0}
.gallery-section .section-label{color:var(--blush)}
.gallery-section .section-label::before{background:var(--blush)}
.gallery-section .section-title{color:var(--ivory)}
.gallery-section .section-title em{color:var(--blush)}
.gallery-masonry{
  columns:4;column-gap:6px;
}
.gallery-masonry img{
  width:100%;break-inside:avoid;margin-bottom:6px;
  transition:.5s;cursor:pointer;
}
.gallery-masonry img:hover{opacity:.8;transform:scale(1.02)}

/* CONTACT */
.contact-section{background:var(--warm)}
.contact-grid{display:grid;grid-template-columns:1fr 1fr;gap:80px;align-items:center}
.contact-form-area{background:var(--ivory);padding:48px;border:1px solid rgba(196,120,138,.1)}
.contact-form-area h3{
  font-family:'Cormorant Garamond',serif;font-size:32px;color:var(--dark);margin-bottom:8px;
}
.contact-form-area p{font-size:13px;color:var(--muted);margin-bottom:32px}
.contact-info-item{
  display:flex;gap:20px;align-items:flex-start;margin-bottom:32px;
}
.ci-icon{
  width:48px;height:48px;background:var(--blush);display:flex;align-items:center;
  justify-content:center;color:var(--dark);font-size:16px;flex-shrink:0;
}
.ci-label{font-size:11px;letter-spacing:2px;text-transform:uppercase;color:var(--muted);margin-bottom:4px}
.ci-val{font-size:16px;color:var(--dark);line-height:1.5}
.wa-link{
  display:inline-flex;align-items:center;gap:12px;
  background:#25D366;color:#fff;padding:16px 32px;
  font-size:13px;letter-spacing:2px;text-transform:uppercase;
  font-weight:500;transition:.3s;margin-top:32px;
}
.wa-link:hover{background:var(--dark)}
.map-embed{height:340px;overflow:hidden}
.map-embed iframe{width:100%;height:100%;border:none;filter:sepia(20%) saturate(.8)}

/* FOOTER */
footer{
  background:var(--dark);padding:60px 48px 40px;
  display:grid;grid-template-columns:1fr 1fr 1fr;gap:48px;
}
.footer-brand .logo{color:var(--ivory);margin-bottom:12px}
.footer-brand .logo em{color:var(--blush)}
.footer-brand p{font-size:13px;color:rgba(255,255,255,.4);line-height:1.7}
.footer-col h4{
  font-size:11px;letter-spacing:3px;text-transform:uppercase;
  color:rgba(255,255,255,.4);margin-bottom:16px;
}
.footer-col a{
  display:block;font-size:14px;color:rgba(255,255,255,.6);
  margin-bottom:8px;transition:.3s;
}
.footer-col a:hover{color:var(--blush)}
.footer-bottom{
  background:var(--dark);border-top:1px solid rgba(255,255,255,.06);
  padding:20px 48px;display:flex;justify-content:space-between;align-items:center;
}
.footer-bottom p{font-size:11px;color:rgba(255,255,255,.25)}

/* WA FLOAT */
.wa-float{
  position:fixed;bottom:24px;right:24px;z-index:150;
  width:56px;height:56px;background:#25D366;border-radius:50%;
  display:flex;align-items:center;justify-content:center;
  font-size:26px;color:#fff;box-shadow:0 4px 20px rgba(37,211,102,.4);
  transition:.3s;
}
.wa-float:hover{transform:scale(1.1)}

/* FADE */
.fade-up{opacity:0;transform:translateY(30px);transition:.8s cubic-bezier(.4,0,.2,1)}
.fade-up.vis{opacity:1;transform:translateY(0)}

@media(max-width:900px){
  .hero{grid-template-columns:1fr}
  .hero-right{height:400px}
  .services-intro{grid-template-columns:1fr}
  .services-grid{grid-template-columns:1fr 1fr}
  .about-grid{grid-template-columns:1fr}
  .contact-grid{grid-template-columns:1fr}
  .gallery-masonry{columns:2}
  footer{grid-template-columns:1fr}
  nav{padding:0 20px}
  .hero-left{padding:60px 24px}
  .container{padding:0 20px}
  .nav-links{display:none}
}
@media(max-width:600px){
  .services-grid{grid-template-columns:1fr}
  .gallery-masonry{columns:2}
  .hero-badges{flex-wrap:wrap}
}
